using System;

// A fake unmanaged resource: only 3 handles exist, like a small connection pool.
class Handle : IDisposable
{
    public const int Max = 3;
    public static int Open = 0;

    public Handle()
    {
        if (Open == Max) throw new InvalidOperationException("no free handles");
        Open++;
    }

    public void Dispose() { Open--; }   // hand the handle back right now
}

class Program
{
    static void Main()
    {
        Console.WriteLine("Handles available: " + Handle.Max + ", jobs to run: 5");

        // 1) With using: Dispose runs at the end of each loop turn.
        for (int job = 1; job <= 5; job++)
        {
            using (var h = new Handle())
                Console.WriteLine("with using, job " + job + ": open handles = " + Handle.Open);
        }

        // 2) Without using: nobody returns the handle, so job 4 cannot get one.
        try
        {
            for (int job = 1; job <= 5; job++)
            {
                var h = new Handle();
                Console.WriteLine("no using,   job " + job + ": open handles = " + Handle.Open);
            }
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine("job 4 failed: " + ex.Message);
        }

        // 3) Managed memory needs no such care: the GC frees these arrays by itself.
        for (int i = 0; i < 1000; i++) { var buffer = new byte[10000]; buffer[0] = 1; }
        Console.WriteLine("1000 arrays created and dropped, no cleanup code needed");
        // Time O(jobs), extra space O(1).
    }
}

using System;

// A class that owns something must pass Dispose on to it.
class Connection : IDisposable
{
    private readonly string _name;
    private bool _disposed;
    public Connection(string name) { _name = name; Console.WriteLine("open  " + _name); }

    public void Send(string text)
    {
        // After Dispose the object must refuse to work.
        if (_disposed) throw new ObjectDisposedException(_name);
        Console.WriteLine(_name + " sends: " + text);
    }

    public void Dispose()
    {
        if (_disposed) return;          // calling Dispose twice must be safe
        _disposed = true;
        Console.WriteLine("close " + _name);
    }
}

class Program
{
    static void Main()
    {
        try
        {
            // Two using declarations: disposed in reverse order at the end of the block.
            using (var first = new Connection("A"))
            using (var second = new Connection("B"))
            {
                first.Send("hello");
                throw new InvalidOperationException("something went wrong");
            }
        }
        catch (InvalidOperationException ex)
        {
            // Both connections were closed before we got here.
            Console.WriteLine("caught: " + ex.Message);
        }

        var c = new Connection("C");
        c.Dispose();
        c.Dispose();                     // second call does nothing
        try { c.Send("late"); }
        catch (ObjectDisposedException) { Console.WriteLine("C refuses to work after Dispose"); }
        // Time O(1), space O(1).
    }
}

using System;
using System.Diagnostics;
using System.Threading.Tasks;

class Program
{
    // The "kitchen": takes 200 ms per dish and uses no thread while cooking.
    static async Task<string> CookAsync(string dish)
    {
        await Task.Delay(200);
        return dish;
    }

    static async Task Main()
    {
        string[] orders = { "soup", "rice", "tea" };
        Console.WriteLine("Orders: " + string.Join(", ", orders) + " (200 ms each)");

        // 1) One by one: the next order starts only when the previous dish is ready.
        var sw = Stopwatch.StartNew();
        foreach (string dish in orders)
            Console.WriteLine("served " + await CookAsync(dish));
        Console.WriteLine("one by one took about " + Round(sw.ElapsedMilliseconds) + " ms");

        // 2) Hand in all orders first (the tasks start now), then await them together.
        sw.Restart();
        Task<string>[] cooking = { CookAsync("soup"), CookAsync("rice"), CookAsync("tea") };
        string[] ready = await Task.WhenAll(cooking);
        Console.WriteLine("served " + string.Join(", ", ready));
        Console.WriteLine("all together took about " + Round(sw.ElapsedMilliseconds) + " ms");
        // Each dish still takes 200 ms. Async did not make cooking faster;
        // it let one waiter (thread) look after all three orders.
        // Time: 600 ms vs 200 ms of waiting. Space O(orders).
    }

    static long Round(long ms) { return ms / 100 * 100; }   // 612 -> 600, to keep the output tidy
}

using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    // CPU-bound: the thread is busy computing the whole time.
    static int CountPrimes(int from, int to)
    {
        int count = 0;
        for (int n = Math.Max(from, 2); n < to; n++)
        {
            bool prime = true;
            for (int d = 2; d * d <= n; d++) if (n % d == 0) { prime = false; break; }
            if (prime) count++;
        }
        return count;
    }

    static async Task Main()
    {
        // I/O-bound: three 150 ms waits overlap on zero threads. This is asynchrony.
        var sw = Stopwatch.StartNew();
        await Task.WhenAll(Task.Delay(150), Task.Delay(150), Task.Delay(150));
        Console.WriteLine("3 waits of 150 ms, overlapped: about " + sw.ElapsedMilliseconds / 50 * 50 + " ms");

        // CPU-bound, one core.
        const int Limit = 2000000, Parts = 4;
        sw.Restart();
        int single = CountPrimes(0, Limit);
        long oneCore = sw.ElapsedMilliseconds;

        // CPU-bound, several cores: split the range, add the parts. This is parallelism.
        sw.Restart();
        int total = 0;
        Parallel.For(0, Parts, part =>
        {
            int found = CountPrimes(part * (Limit / Parts), (part + 1) * (Limit / Parts));
            Interlocked.Add(ref total, found);      // shared total, so add atomically
        });
        long manyCores = sw.ElapsedMilliseconds;

        Console.WriteLine("primes below " + Limit + ": " + single + " (one core), " + total + " (" + Parts + " parts)");
        Console.WriteLine("same answer: " + (single == total));
        Console.WriteLine("parallel was faster: " + (manyCores < oneCore) + " on " + Environment.ProcessorCount + " cores");
        // Time O(n * sqrt(n)) of CPU work either way; parallelism divides the clock time by the cores.
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

// What the compiler generates for:
//   async Task<string> GetOrderAsync(int id) { var o = await FindAsync(id); return "Order " + o; }
class GetOrderStateMachine
{
    public int State;                      // which await we reached
    public int Id;                         // parameters and locals become fields
    private Task<int> _pending;
    public readonly TaskCompletionSource<string> Builder = new TaskCompletionSource<string>();

    public void MoveNext()
    {
        if (State == 0)
        {
            Console.WriteLine("state 0: runs on the caller's thread, starts the query");
            _pending = FindAsync(Id);
            State = 1;                     // remember where to continue
            if (!_pending.IsCompleted)
            {
                // Not finished: ask to be called back, then RETURN. The thread is free.
                _pending.ContinueWith(t => MoveNext());
                Console.WriteLine("state 0: task not finished, place saved, returning to caller");
                return;
            }
        }
        // State 1: the code after the await.
        Console.WriteLine("state 1: resumed, pool thread = " + Thread.CurrentThread.IsThreadPoolThread);
        Builder.SetResult("Order " + _pending.Result);   // task is complete, so no blocking here
    }

    static async Task<int> FindAsync(int id) { await Task.Delay(100); return id; }
}

class Program
{
    static void Main()
    {
        var machine = new GetOrderStateMachine { Id = 42 };
        machine.MoveNext();                           // like calling GetOrderAsync(42)
        Task<string> task = machine.Builder.Task;     // the Task the caller receives
        Console.WriteLine("caller: got a Task, completed = " + task.IsCompleted + ", free to do other work");
        Console.WriteLine("caller: result = " + task.GetAwaiter().GetResult());   // a console Main may wait
        // Time: one extra object and one callback per await that really waits. Space O(1).
    }
}

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static readonly Dictionary<int, decimal> Cache = new Dictionary<int, decimal>();

    // ValueTask: on a cache hit the result is returned with no Task object created.
    static ValueTask<decimal> GetPriceAsync(int id)
    {
        if (Cache.TryGetValue(id, out decimal price)) return new ValueTask<decimal>(price);
        return new ValueTask<decimal>(LoadAsync(id));        // slow path: wrap a real Task
    }

    static async Task<decimal> LoadAsync(int id)
    {
        await Task.Delay(50);                                // pretend database call
        return Cache[id] = id * 1.5m;
    }

    static async Task Main()
    {
        // 1) Thread: a dedicated worker you create and own.
        var thread = new Thread(() =>
            Console.WriteLine("Thread:     pool thread = " + Thread.CurrentThread.IsThreadPoolThread));
        thread.Start();
        thread.Join();

        // 2) Task.Run: borrows a worker from the shared pool.
        await Task.Run(() =>
            Console.WriteLine("Task.Run:   pool thread = " + Thread.CurrentThread.IsThreadPoolThread));

        // 3) A Task is only a promise. This one has no thread at all while it is pending.
        var promise = new TaskCompletionSource<string>();
        Console.WriteLine("Promise:    completed = " + promise.Task.IsCompleted);
        promise.SetResult("done");
        Console.WriteLine("Promise:    result = " + await promise.Task);

        // 4) ValueTask: first call waits, second call is already complete.
        ValueTask<decimal> miss = GetPriceAsync(10);
        Console.WriteLine("ValueTask:  first call completed at once = " + miss.IsCompleted);
        Console.WriteLine("ValueTask:  price = " + await miss);
        ValueTask<decimal> hit = GetPriceAsync(10);
        Console.WriteLine("ValueTask:  second call completed at once = " + hit.IsCompleted);
        Console.WriteLine("ValueTask:  price = " + await hit);
        // Time O(1) per call. A cache hit allocates nothing; a miss allocates one Task.
    }
}

using System;
using System.Diagnostics;
using System.Threading.Tasks;

class Program
{
    static async Task<int> GetStockAsync() { await Task.Delay(150); return 7; }
    static async Task<decimal> GetPriceAsync() { await Task.Delay(150); return 19.5m; }

    static async Task SaveAsync(bool fail)
    {
        await Task.Delay(20);
        if (fail) throw new InvalidOperationException("database is down");
    }

    static async Task Main()
    {
        // Mistake 1: two independent calls awaited one after the other.
        var sw = Stopwatch.StartNew();
        int stock = await GetStockAsync();
        decimal price = await GetPriceAsync();
        Console.WriteLine("one by one: stock " + stock + ", price " + price + ", about " + sw.ElapsedMilliseconds / 50 * 50 + " ms");

        // Fix: start both, then await both. Total time = the slower call.
        sw.Restart();
        Task<int> stockTask = GetStockAsync();
        Task<decimal> priceTask = GetPriceAsync();
        await Task.WhenAll(stockTask, priceTask);
        Console.WriteLine("together:   stock " + await stockTask + ", price " + await priceTask + ", about " + sw.ElapsedMilliseconds / 50 * 50 + " ms");

        // Mistake 2: the await is missing, so the failure is never seen here.
        Task forgotten = SaveAsync(true);
        Console.WriteLine("no await:   code says 'saved' although the save will fail");
        await Task.Delay(100);
        Console.WriteLine("no await:   the task failed silently = " + forgotten.IsFaulted);

        // Fix: await it, and the exception arrives where you can handle it.
        try
        {
            await SaveAsync(true);
            Console.WriteLine("saved");
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine("with await: caught '" + ex.Message + "'");
        }
        // Time: 300 ms vs 150 ms of waiting. Space O(1).
    }
}

using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int _calls;

    // Fails twice with a temporary error, then works.
    static async Task<string> FlakyAsync(CancellationToken ct)
    {
        _calls++;
        await Task.Delay(20, ct);
        if (_calls < 3) throw new TimeoutException("temporary failure");
        return "order saved";
    }

    // Retry only temporary errors, wait longer each time: 50, 100, 200 ms...
    static async Task<T> RetryAsync<T>(Func<CancellationToken, Task<T>> work, int maxAttempts, CancellationToken ct)
    {
        for (int attempt = 1; ; attempt++)
        {
            try { return await work(ct); }
            catch (TimeoutException ex) when (attempt < maxAttempts)
            {
                int delay = 50 * (1 << (attempt - 1));     // real code also adds a small random part
                Console.WriteLine("attempt " + attempt + " failed (" + ex.Message + "), waiting " + delay + " ms");
                await Task.Delay(delay, ct);               // the wait can be cancelled too
            }
        }
    }

    static async Task Main()
    {
        string result = await RetryAsync(FlakyAsync, 4, CancellationToken.None);
        Console.WriteLine("attempt " + _calls + " succeeded: " + result);

        // Timeout: the token is cancelled after 100 ms and the 5-second call stops early.
        using (var cts = new CancellationTokenSource())
        {
            cts.CancelAfter(100);
            var sw = Stopwatch.StartNew();
            try
            {
                await Task.Delay(5000, cts.Token);         // stands for a slow query
                Console.WriteLine("finished");
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine("slow call cancelled before 1 second: " + (sw.ElapsedMilliseconds < 1000));
            }
        }
        // Time: at most maxAttempts calls plus 50 * (2^attempts - 1) ms of waiting. Space O(1).
    }
}

using System;
using System.Threading.Tasks;

class Program
{
    static async Task<int> CallAsync(string name, int ms, bool fail)
    {
        await Task.Delay(ms);
        if (fail) throw new InvalidOperationException(name + " failed");
        return ms;
    }

    static async Task Main()
    {
        // Three calls start now. A fails after 80 ms, C fails after 20 ms, B works.
        Task<int> a = CallAsync("A", 80, true);
        Task<int> b = CallAsync("B", 50, false);
        Task<int> c = CallAsync("C", 20, true);
        Task<int[]> all = Task.WhenAll(a, b, c);
        try
        {
            await all;                                   // waits for ALL three, then throws
        }
        catch (Exception ex)
        {
            // await rethrows only one exception (the first task in the list that failed).
            Console.WriteLine("await threw:        " + ex.Message);
            // The task itself keeps every failure.
            foreach (Exception inner in all.Exception.InnerExceptions)
                Console.WriteLine("all.Exception has:  " + inner.Message);
            Console.WriteLine("B still succeeded:  " + (b.Status == TaskStatus.RanToCompletion) + ", result " + b.Result);
        }

        // WhenAny returns the first task that finishes. Used here as a timeout.
        Task<int> slow = CallAsync("slow", 2000, false);
        Task winner = await Task.WhenAny(slow, Task.Delay(100));
        if (winner == slow) Console.WriteLine("slow call finished in time");
        else Console.WriteLine("timeout after 100 ms; slow call still running = " + !slow.IsCompleted);
        // Time: WhenAll = the slowest task, WhenAny = the fastest task. Space O(tasks).
    }
}

using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int _unsafe, _atomic, _locked;
    static readonly object Gate = new object();          // private object used only as a lock
    static readonly ConcurrentDictionary<string, int> Hits = new ConcurrentDictionary<string, int>();

    static void Main()
    {
        const int Workers = 4, PerWorker = 200000;
        Console.WriteLine(Workers + " workers x " + PerWorker + " increments, expected " + Workers * PerWorker);

        Parallel.For(0, Workers, worker =>
        {
            string page = worker % 2 == 0 ? "/home" : "/cart";
            for (int i = 0; i < PerWorker; i++)
            {
                _unsafe++;                                // read, add, write: updates get lost
                Interlocked.Increment(ref _atomic);       // one atomic CPU step
                lock (Gate) { _locked++; }                // one thread at a time
                Hits.AddOrUpdate(page, 1, (key, old) => old + 1);   // safe read-modify-write per key
            }
        });

        Console.WriteLine("plain ++     : " + _unsafe + (_unsafe < Workers * PerWorker ? "  (updates were lost)" : "  (lucky run)"));
        Console.WriteLine("Interlocked  : " + _atomic);
        Console.WriteLine("lock         : " + _locked);
        Console.WriteLine("dictionary   : /home " + Hits["/home"] + ", /cart " + Hits["/cart"]);
        // Time O(workers * increments). Space O(1) plus one entry per page.
    }
}

using System;
using System.Threading;

class Program
{
    static readonly object AccountA = new object();
    static readonly object AccountB = new object();

    // Takes "first", waits until the other thread also holds its first lock, then wants "second".
    // TryEnter with a timeout lets the demo report the deadlock and not hang forever.
    static bool Transfer(object first, object second, Barrier bothHoldOne)
    {
        lock (first)
        {
            bothHoldOne.SignalAndWait();
            if (!Monitor.TryEnter(second, 300)) return false;    // gave up: the other thread owns it
            Monitor.Exit(second);
            return true;
        }
    }

    static void Main()
    {
        // Bug: thread 1 locks A then B, thread 2 locks B then A.
        var barrier = new Barrier(2);
        bool ok1 = false, ok2 = false;
        var t1 = new Thread(() => ok1 = Transfer(AccountA, AccountB, barrier));
        var t2 = new Thread(() => ok2 = Transfer(AccountB, AccountA, barrier));
        t1.Start(); t2.Start(); t1.Join(); t2.Join();
        Console.WriteLine("opposite order: thread 1 got both locks = " + ok1 + ", thread 2 got both locks = " + ok2);
        Console.WriteLine("with a plain lock (no timeout) both threads would wait forever");

        // Fix: every thread takes the locks in the same order, A before B.
        int done = 0;
        ThreadStart sameOrder = () =>
        {
            for (int i = 0; i < 100000; i++)
                lock (AccountA) { lock (AccountB) { done++; } }
        };
        var t3 = new Thread(sameOrder);
        var t4 = new Thread(sameOrder);
        t3.Start(); t4.Start(); t3.Join(); t4.Join();
        Console.WriteLine("same order: " + done + " transfers finished, no deadlock");
        // Time O(transfers). Space O(1).
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Channels;
using System.Threading.Tasks;

class Program
{
    // IAsyncEnumerable: items arrive one at a time; the reader awaits each one.
    static async IAsyncEnumerable<string> ReadPagesAsync(int pages)
    {
        for (int page = 1; page <= pages; page++)
        {
            await Task.Delay(20);                 // pretend to fetch one page from an API
            yield return "page " + page;
        }
    }

    static async Task Main()
    {
        // 1) Back-pressure: a bounded channel refuses work when it is full.
        Channel<int> small = Channel.CreateBounded<int>(2);
        for (int job = 1; job <= 3; job++)
            Console.WriteLine("TryWrite(job " + job + ") accepted = " + small.Writer.TryWrite(job));

        // 2) Producer and consumer run at the same time, passing 100 numbers.
        Channel<int> channel = Channel.CreateBounded<int>(10);
        Task producer = Task.Run(async () =>
        {
            for (int i = 1; i <= 100; i++)
                await channel.Writer.WriteAsync(i);   // waits (no thread blocked) while the channel is full
            channel.Writer.Complete();                // tells the reader "no more items"
        });
        int sum = 0, count = 0;
        await foreach (int item in channel.Reader.ReadAllAsync())
        {
            sum += item;
            count++;
        }
        await producer;
        Console.WriteLine("consumer read " + count + " items, sum = " + sum);

        // 3) Pull a stream with await foreach.
        await foreach (string page in ReadPagesAsync(3))
            Console.WriteLine("got " + page);
        // Time O(items). Space: at most 10 items are in memory in the channel at once.
    }
}

using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int _inFlight, _peak;

    // A pretend HTTP call of 50 ms that records how many calls run at the same moment.
    static async Task CallApiAsync(int id)
    {
        int now = Interlocked.Increment(ref _inFlight);
        int seen;
        while (now > (seen = _peak) && Interlocked.CompareExchange(ref _peak, now, seen) != seen) { }
        await Task.Delay(50);
        Interlocked.Decrement(ref _inFlight);
    }

    static async Task Main()
    {
        int[] ids = Enumerable.Range(1, 40).ToArray();
        Console.WriteLine("40 calls of 50 ms each");

        // 1) WhenAll: every call starts at once. Fine for 3 calls, risky for 5,000.
        await Task.WhenAll(ids.Select(CallApiAsync));
        Console.WriteLine("Task.WhenAll:           most calls at the same time = " + _peak);

        // 2) ForEachAsync: the same work, but never more than 5 in flight.
        _peak = 0;
        var options = new ParallelOptions { MaxDegreeOfParallelism = 5 };
        await Parallel.ForEachAsync(ids, options, async (id, ct) => await CallApiAsync(id));
        Console.WriteLine("Parallel.ForEachAsync:  most calls at the same time = " + _peak);

        // 3) PLINQ: CPU work on in-memory data, spread over the cores.
        long sumOfSquares = Enumerable.Range(1, 1000000).AsParallel().Sum(n => (long)n * n % 7);
        Console.WriteLine("PLINQ sum over 1,000,000 numbers = " + sumOfSquares);
        // Time: 40 calls / 5 at once * 50 ms = about 400 ms for (2), about 50 ms for (1).
        // Space O(items) for WhenAll (40 tasks), O(limit) for ForEachAsync.
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class ExpiringCache<TValue>
{
    private class Entry { public TValue Value; public DateTime Expires; }
    private readonly ConcurrentDictionary<string, Lazy<Entry>> _map = new ConcurrentDictionary<string, Lazy<Entry>>();
    private readonly TimeSpan _lifetime;
    private readonly Func<DateTime> _now;                 // the clock is passed in, so tests can move time

    public ExpiringCache(TimeSpan lifetime, Func<DateTime> now) { _lifetime = lifetime; _now = now; }

    public TValue GetOrAdd(string key, Func<string, TValue> load)
    {
        while (true)
        {
            // Lazy makes the load run once, even if many threads miss at the same moment.
            Lazy<Entry> lazy = _map.GetOrAdd(key, k => new Lazy<Entry>(
                () => new Entry { Value = load(k), Expires = _now() + _lifetime }));
            Entry entry = lazy.Value;
            if (entry.Expires > _now()) return entry.Value;
            // Expired: remove exactly this entry (not a newer one), then try again.
            ((ICollection<KeyValuePair<string, Lazy<Entry>>>)_map).Remove(new KeyValuePair<string, Lazy<Entry>>(key, lazy));
        }
    }
}

class Program
{
    static void Main()
    {
        DateTime clock = new DateTime(2026, 1, 1, 12, 0, 0);
        int loads = 0;
        var cache = new ExpiringCache<string>(TimeSpan.FromMinutes(5), () => clock);
        Func<string, string> slowLoad = key =>
        {
            Interlocked.Increment(ref loads);
            Thread.Sleep(100);                             // pretend database query
            return "product " + key;
        };

        Parallel.For(0, 8, i => cache.GetOrAdd("42", slowLoad));   // 8 callers, same cold key
        Console.WriteLine("8 callers at once  -> value '" + cache.GetOrAdd("42", slowLoad) + "', loads = " + loads);

        clock = clock.AddMinutes(4);
        cache.GetOrAdd("42", slowLoad);
        Console.WriteLine("4 minutes later    -> still cached, loads = " + loads);

        clock = clock.AddMinutes(2);
        cache.GetOrAdd("42", slowLoad);
        Console.WriteLine("6 minutes in total -> expired and reloaded, loads = " + loads);
        // Time O(1) per read. Space O(keys); a real cache also needs a size limit.
    }
}

using System;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task Main()
    {
        const int Requests = 40, WaitMs = 250;
        Console.WriteLine(Requests + " requests, each waits " + WaitMs + " ms on a 'database'. Cores: " + Environment.ProcessorCount);

        // 1) Blocking: every request holds a pool thread for the whole wait (like .Result).
        var sw = Stopwatch.StartNew();
        Task[] blocking = Enumerable.Range(0, Requests)
            .Select(i => Task.Run(() => Thread.Sleep(WaitMs)))
            .ToArray();
        await Task.Delay(100);
        // Work is queued although the CPU is idle: that queue is the starvation.
        long queuedEarly = ThreadPool.PendingWorkItemCount;
        await Task.WhenAll(blocking);
        long blockedMs = sw.ElapsedMilliseconds;
        Console.WriteLine("blocking: requests still queued after 100 ms = " + (queuedEarly > 0));
        Console.WriteLine("blocking: pool grew to " + ThreadPool.ThreadCount + " threads");

        // 2) Async: no thread is held during the wait, so all 40 overlap.
        sw.Restart();
        Task[] waiting = Enumerable.Range(0, Requests)
            .Select(async i => await Task.Delay(WaitMs))
            .ToArray();
        await Task.WhenAll(waiting);
        long asyncMs = sw.ElapsedMilliseconds;

        Console.WriteLine("blocking took " + blockedMs + " ms, async took " + asyncMs + " ms");
        Console.WriteLine("async was at least twice as fast: " + (asyncMs * 2 < blockedMs));
        // The numbers vary by machine. The pattern does not: blocked threads, queued work, idle CPU.
        // Time: blocking = requests / threads * wait; async = one wait. Space: about 1 MB of stack per extra thread.
    }
}

using System;

struct PointStruct { public int X; }     // value type: the variable holds the data itself
class PointClass { public int X; }       // reference type: the variable holds a pointer to the heap

class Program
{
    static void Main()
    {
        // Copying a struct copies the data. Copying a class variable copies the pointer.
        PointStruct s1 = new PointStruct { X = 1 };
        PointStruct s2 = s1;
        s2.X = 99;
        PointClass c1 = new() { X = 1 };
        PointClass c2 = c1;
        c2.X = 99;
        Console.WriteLine("struct: s1.X = " + s1.X + " (unchanged, s2 is a separate copy)");
        Console.WriteLine("class:  c1.X = " + c1.X + " (changed, c1 and c2 are the same object)");

        // A new object starts in generation 0. Each collection it survives moves it up.
        var order = new PointClass();
        Console.WriteLine("new object:             generation " + GC.GetGeneration(order));
        GC.Collect();                    // demo only: never call this in production code
        Console.WriteLine("after 1 collection:     generation " + GC.GetGeneration(order));
        GC.Collect();
        Console.WriteLine("after 2 collections:    generation " + GC.GetGeneration(order));

        // 85,000 bytes or more goes straight to the Large Object Heap, which is collected with gen 2.
        var small = new byte[1000];
        var large = new byte[100000];
        Console.WriteLine("1,000-byte array:       generation " + GC.GetGeneration(small));
        Console.WriteLine("100,000-byte array:     generation " + GC.GetGeneration(large));

        // Short-lived garbage is cleaned by cheap gen 0 collections.
        int before = GC.CollectionCount(0);
        for (int i = 0; i < 200000; i++) { var temp = new byte[1000]; temp[0] = 1; }
        Console.WriteLine("200,000 temporary arrays caused gen 0 collections: " + (GC.CollectionCount(0) > before));
        GC.KeepAlive(order);
        // Time O(1) per allocation; a gen 0 collection costs only the survivors.
    }
}

using System;
using System.Runtime.CompilerServices;

class PriceFeed
{
    public event EventHandler PriceChanged;     // holds a delegate list; each delegate points at its subscriber
}

class Screen
{
    public Screen(PriceFeed feed, bool subscribe)
    {
        if (subscribe) feed.PriceChanged += OnPriceChanged;
    }
    public void Detach(PriceFeed feed) { feed.PriceChanged -= OnPriceChanged; }
    private void OnPriceChanged(object sender, EventArgs e) { }
}

class Program
{
    static readonly PriceFeed Feed = new();    // a static field is a GC root: it lives for the whole run

    // Created in a helper so that no local variable of Main points at the Screen.
    [MethodImpl(MethodImplOptions.NoInlining)]
    static WeakReference CreateScreen(bool subscribe)
    {
        return new WeakReference(new Screen(Feed, subscribe));   // a weak reference does not keep it alive
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    static void Unsubscribe(WeakReference screen) { ((Screen)screen.Target).Detach(Feed); }

    static void Collect() { GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect(); }   // demo only

    static void Main()
    {
        WeakReference plain = CreateScreen(false);
        WeakReference subscribed = CreateScreen(true);
        Collect();
        Console.WriteLine("screen with no references:        alive = " + plain.IsAlive);
        Console.WriteLine("screen subscribed to static feed: alive = " + subscribed.IsAlive + "   (root: static Feed -> event -> screen)");

        Unsubscribe(subscribed);
        Collect();
        Console.WriteLine("after unsubscribing:              alive = " + subscribed.IsAlive);
        // Time O(1). Each forgotten subscription costs one object that can never be freed.
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

// A pretend database that counts round trips. Each trip costs about 2 ms of network time.
class FakeDb
{
    public int RoundTrips;
    private readonly List<int[]> _orders = Enumerable.Range(1, 50).Select(i => new[] { i, i % 10 + 1 }).ToList();
    private readonly Dictionary<int, string> _customers = Enumerable.Range(1, 10).ToDictionary(i => i, i => "customer" + i);

    public List<int[]> GetOrders() { RoundTrips++; return _orders; }               // [orderId, customerId]
    public string GetCustomer(int id) { RoundTrips++; return _customers[id]; }
    public Dictionary<int, string> GetCustomers(IEnumerable<int> ids)
    {
        RoundTrips++;                                                               // one query: WHERE Id IN (...)
        return ids.Distinct().ToDictionary(id => id, id => _customers[id]);
    }
}

class Program
{
    static void Main()
    {
        const int MsPerTrip = 2;

        // Slow: 1 query for the orders, then 1 query per order for its customer.
        var db = new FakeDb();
        var slow = new List<string>();
        foreach (int[] order in db.GetOrders())
            slow.Add(order[0] + ":" + db.GetCustomer(order[1]));
        Console.WriteLine("N+1 version:   " + db.RoundTrips + " round trips, about " + db.RoundTrips * MsPerTrip + " ms of waiting");

        // Fast: 1 query for the orders, 1 query for all the customers they need.
        db = new FakeDb();
        List<int[]> orders = db.GetOrders();
        Dictionary<int, string> customers = db.GetCustomers(orders.Select(o => o[1]));
        List<string> fast = orders.Select(o => o[0] + ":" + customers[o[1]]).ToList();
        Console.WriteLine("batch version: " + db.RoundTrips + " round trips, about " + db.RoundTrips * MsPerTrip + " ms of waiting");

        Console.WriteLine("same result: " + slow.SequenceEqual(fast) + ", first rows: " + string.Join(", ", fast.Take(3)));
        // Time: N+1 queries vs 2 queries. Space O(N) for both.
    }
}

using System;

class Program
{
    // Allocating version: Split creates an array and 2 strings, and each inner Split creates more.
    static int ReadIdWithSplit(string line)
    {
        string first = line.Split(';')[0];          // "id=42"
        return int.Parse(first.Split('=')[1]);      // "42"
    }

    // Span version: every slice is only a view (pointer + length) onto the same string.
    static int ReadIdWithSpan(ReadOnlySpan<char> line)
    {
        ReadOnlySpan<char> first = line.Slice(0, line.IndexOf(';'));   // "id=42", no new string
        ReadOnlySpan<char> number = first.Slice(first.IndexOf('=') + 1); // "42"
        return int.Parse(number);
    }

    static void Main()
    {
        string line = "id=42;name=Asha";
        const int Lines = 100000;
        Console.WriteLine("input: " + line + ", parsed " + Lines + " times");

        long before = GC.GetAllocatedBytesForCurrentThread();
        long sum1 = 0;
        for (int i = 0; i < Lines; i++) sum1 += ReadIdWithSplit(line);
        long splitBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        before = GC.GetAllocatedBytesForCurrentThread();
        long sum2 = 0;
        for (int i = 0; i < Lines; i++) sum2 += ReadIdWithSpan(line);
        long spanBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        Console.WriteLine("Split: id = " + sum1 / Lines + ", allocated about " + splitBytes / 1024 / 1024 + " MB");
        Console.WriteLine("Span:  id = " + sum2 / Lines + ", allocated " + spanBytes + " bytes");

        // A Span over an array is a window: writing through it changes the array.
        int[] numbers = { 1, 2, 3, 4, 5 };
        Span<int> middle = numbers.AsSpan(1, 3);    // 2, 3, 4
        middle[0] = 20;
        Console.WriteLine("array after writing through the span: " + string.Join(", ", numbers));

        Span<byte> small = stackalloc byte[16];     // 16 bytes on the stack, no heap object at all
        small[0] = 7;
        Console.WriteLine("stackalloc buffer length " + small.Length + ", first byte " + small[0]);
        // Time O(length) for both parsers. Space: O(1) for Span, several objects per line for Split.
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // The leak: a static list that only ever gets Add. Static = GC root, so nothing in it can be freed.
    static readonly List<byte[]> AuditLog = new List<byte[]>();

    // The fix: keep at most 100 entries; the oldest is dropped and becomes garbage.
    static readonly Queue<byte[]> BoundedLog = new Queue<byte[]>();
    const int Limit = 100;

    static void HandleRequestLeaky() { AuditLog.Add(new byte[10000]); }

    static void HandleRequestBounded()
    {
        BoundedLog.Enqueue(new byte[10000]);
        if (BoundedLog.Count > Limit) BoundedLog.Dequeue();
    }

    // Memory still in use after a full collection (demo only; do not call GC.Collect in a service).
    static long LiveMegabytes() { return GC.GetTotalMemory(true) / 1024 / 1024; }

    static void Main()
    {
        long start = LiveMegabytes();
        Console.WriteLine("5,000 requests, each records 10,000 bytes");

        for (int i = 0; i < 5000; i++) HandleRequestLeaky();
        long afterLeak = LiveMegabytes();
        Console.WriteLine("unbounded static list: " + AuditLog.Count + " entries kept, memory grew by about "
            + (afterLeak - start) + " MB even after a full GC");

        for (int i = 0; i < 5000; i++) HandleRequestBounded();
        long afterBounded = LiveMegabytes();
        Console.WriteLine("bounded queue:         " + BoundedLog.Count + " entries kept, memory grew by about "
            + (afterBounded - afterLeak) + " MB");

        AuditLog.Clear();                           // removing the references is the only real fix
        Console.WriteLine("after clearing the list, memory is back near the start: "
            + (LiveMegabytes() - start < 5));
        // Time O(1) per request. Space: O(requests) for the leak, O(Limit) for the bounded log.
    }
}

