using System;
using System.Collections.Generic;

enum Lifetime { Transient, Scoped, Singleton }

class Container
{
    private readonly Dictionary<Type, (Lifetime life, Func<Scope, object> make)> _map =
        new Dictionary<Type, (Lifetime, Func<Scope, object>)>();
    private readonly Dictionary<Type, object> _singletons = new Dictionary<Type, object>();

    public void Add<T>(Lifetime life, Func<Scope, T> make) { _map[typeof(T)] = (life, s => make(s)); }
    public Scope CreateScope() { return new Scope(this); }

    public object Resolve(Type t, Scope scope)
    {
        var reg = _map[t];
        if (reg.life == Lifetime.Singleton)
        {
            if (!_singletons.TryGetValue(t, out object s)) _singletons[t] = s = reg.make(scope);
            return s;
        }
        if (reg.life == Lifetime.Scoped)
        {
            if (!scope.Instances.TryGetValue(t, out object s)) scope.Instances[t] = s = reg.make(scope);
            return s;
        }
        return reg.make(scope);                       // transient: a new object every time
    }
}

class Scope
{
    public readonly Dictionary<Type, object> Instances = new Dictionary<Type, object>();
    private readonly Container _c;
    public Scope(Container c) { _c = c; }
    public T Get<T>() { return (T)_c.Resolve(typeof(T), this); }
}

class Clock { }                                              // singleton
class DbContext { }                                          // scoped (one per request)
class Mailer { }                                             // transient
class OrderService { public DbContext Db; public OrderService(DbContext db) { Db = db; } }

class Program
{
    static void Main()
    {
        var c = new Container();
        c.Add(Lifetime.Singleton, s => new Clock());
        c.Add(Lifetime.Scoped, s => new DbContext());
        c.Add(Lifetime.Transient, s => new Mailer());
        c.Add(Lifetime.Transient, s => new OrderService(s.Get<DbContext>()));

        Scope r1 = c.CreateScope(), r2 = c.CreateScope();
        Console.WriteLine("singleton same across requests: " + ReferenceEquals(r1.Get<Clock>(), r2.Get<Clock>()));
        Console.WriteLine("scoped same inside one request: " + ReferenceEquals(r1.Get<DbContext>(), r1.Get<OrderService>().Db));
        Console.WriteLine("scoped differs across requests: " + !ReferenceEquals(r1.Get<DbContext>(), r2.Get<DbContext>()));
        Console.WriteLine("transient always new:           " + !ReferenceEquals(r1.Get<Mailer>(), r1.Get<Mailer>()));
        // Time O(1) per resolve, space O(registered types).
    }
}

