// This is what the generator would write for us (it is shown here by hand).
// Because it is plain C#, there is no reflection at run time, and it works with Native AOT.
partial class Customer
{
    public string ToDisplayString()
    {
        return "Customer { Id = " + Id + ", Name = " + Name + " }";
    }
}

class Program
{
    // Analyzer idea: a rule that inspects code and reports a problem. Here the "rule" is run on a type.
    static void CheckRule(Type t)
    {
        foreach (MethodInfo m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        {
            // Rule: public async methods should end with "Async".
            bool isAsync = m.GetCustomAttribute<System.Runtime.CompilerServices.AsyncStateMachineAttribute>() != null;
            if (isAsync && !m.Name.EndsWith("Async"))
                Console.WriteLine("WARNING: " + t.Name + "." + m.Name + " is async but does not end with Async");
        }
    }

    static void Main()
    {
        Console.WriteLine(new Customer().ToDisplayString());
        CheckRule(typeof(Service));
        Console.WriteLine("generator methods on Customer: " + string.Join(", ",
            typeof(Customer).GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
                .Select(m => m.Name).Where(n => n.StartsWith("To"))));
        // Real analyzers and generators run inside the compiler (Roslyn) while you build, not at run time.
        // Time O(1), space O(1).
    }
}

