using System;
using System.Linq;
using System.Reflection;

class EmailHandler { public string Handle() { return "email sent"; } }
class SmsHandler { public string Handle() { return "sms sent"; } }

class Program
{
    // Reflection by NAME: the trimmer sees only a string, so it cannot know which class
    // is needed and may remove it from the published file. Native AOT cannot create it either.
    static string RunByName(string typeName)
    {
        Type t = Type.GetType(typeName);
        if (t == null) return "type not found (it could have been trimmed away)";
        object handler = Activator.CreateInstance(t);
        return (string)t.GetMethod("Handle").Invoke(handler, null);
    }

    // Trim-friendly: the types are named in code, so the trimmer and the compiler can see them.
    static string RunDirect(string kind)
    {
        switch (kind)
        {
            case "email": return new EmailHandler().Handle();
            case "sms": return new SmsHandler().Handle();
            default: return "unknown kind";
        }
    }

    static void Main()
    {
        Console.WriteLine("by name   : " + RunByName("EmailHandler"));
        Console.WriteLine("by name   : " + RunByName("PushHandler"));
        Console.WriteLine("direct    : " + RunDirect("sms"));

        // Where the answer to "which class?" comes from is the whole issue:
        string[] known = typeof(Program).Assembly.GetTypes()
            .Where(t => t.Name.EndsWith("Handler")).Select(t => t.Name).OrderBy(n => n).ToArray();
        Console.WriteLine("types found by scanning the assembly: " + string.Join(", ", known));
        Console.WriteLine("(a trimmed app scans a smaller assembly; a Native AOT app cannot scan at all)");
        // Fix in real projects: source generators (System.Text.Json context), DynamicallyAccessedMembers attributes.
        // Time O(types) for the scan, space O(types).
    }
}

using System;
using System.Collections.Generic;

// A type that cannot hold an invalid value: validate once, in the constructor.
public sealed record EmailAddress
{
    public string Value { get; }
    private EmailAddress(string value) { Value = value; }

    public static bool TryCreate(string input, out EmailAddress email)
    {
        email = null;
        if (string.IsNullOrWhiteSpace(input) || !input.Contains("@")) return false;
        email = new EmailAddress(input.Trim().ToLowerInvariant());
        return true;
    }
}

public sealed class OrderBook
{
    private readonly List<string> _orders = new List<string>();      // internal, can change
    public void Add(string order) { _orders.Add(order); }

    // Return the smallest useful read-only type; callers cannot add to or clear our list.
    public IReadOnlyList<string> Orders { get { return _orders; } }

    // Growing without breaking: keep the old signature, add an overload with an optional detail.
    public string Describe() { return Describe(false); }
    public string Describe(bool includeCount) { return includeCount ? _orders.Count + " orders" : "orders"; }
}

class Program
{
    static void Main()
    {
        foreach (string text in new[] { "  Asha@Example.test ", "not-an-email" })
        {
            if (EmailAddress.TryCreate(text, out EmailAddress e)) Console.WriteLine("'" + text + "' -> valid: " + e.Value);
            else Console.WriteLine("'" + text + "' -> rejected, so no EmailAddress object can ever be invalid");
        }

        var book = new OrderBook();
        book.Add("A1"); book.Add("A2");
        IReadOnlyList<string> view = book.Orders;
        Console.WriteLine("view count " + view.Count + ", Describe() = " + book.Describe() + ", Describe(true) = " + book.Describe(true));
        book.Add("A3");
        Console.WriteLine("the view follows the owner: " + view.Count + " (but a caller cannot change it)");
        // Time O(1) for each call, space O(orders).
    }
}

using System;
using System.Collections.Generic;

readonly record struct Result<T>(bool IsSuccess, T Value, string Error, int Code)
{
    public static Result<T> Ok(T value) => new Result<T>(true, value, null, 200);
    public static Result<T> Fail(string error, int code) => new Result<T>(false, default, error, code);
}

class OrderService
{
    private readonly Dictionary<int, decimal> _stock = new Dictionary<int, decimal> { { 1, 5 }, { 2, 0 } };

    // Expected failures (not found, out of stock) are return values, not exceptions.
    public Result<string> Place(int productId, int quantity)
    {
        if (quantity <= 0) return Result<string>.Fail("quantity must be positive", 400);
        if (!_stock.ContainsKey(productId)) return Result<string>.Fail("product not found", 404);
        if (_stock[productId] < quantity) return Result<string>.Fail("not enough stock", 409);
        _stock[productId] -= quantity;
        return Result<string>.Ok("order placed for product " + productId);
    }
}

class Program
{
    // One place converts a result to the HTTP answer (a Problem Details style body).
    static string ToHttp(Result<string> r)
    {
        if (r.IsSuccess) return "200 OK " + r.Value;
        return r.Code + " {\"title\":\"" + r.Error + "\",\"status\":" + r.Code + "}";
    }

    static void Main()
    {
        var service = new OrderService();
        (int product, int qty)[] calls = { (1, 2), (1, 9), (3, 1), (2, 1), (1, 0) };
        foreach (var call in calls)
            Console.WriteLine("product " + call.product + " x" + call.qty + " -> " + ToHttp(service.Place(call.product, call.qty)));

        // Exceptions stay for the unexpected: a bug or a broken database is not a normal answer.
        try { throw new InvalidOperationException("database connection lost"); }
        catch (InvalidOperationException ex) { Console.WriteLine("500 unexpected -> logged, client sees only a generic message (not '" + ex.Message + "')"); }
        // Time O(1), space O(1). A thrown exception costs microseconds, a returned result almost nothing.
    }
}

using System;
using System.Globalization;
using System.Threading.Tasks;

class Program
{
    // 1) Correctness: culture-sensitive comparison and parsing give different answers on different machines.
    static void CultureBug()
    {
        var germany = new CultureInfo("de-DE");
        var us = new CultureInfo("en-US");
        Console.WriteLine("parse \"1,5\" as de-DE: " + double.Parse("1,5", germany) + ", as en-US: " + double.Parse("1,5", us));
        Console.WriteLine("Fix: pass CultureInfo.InvariantCulture for data, and StringComparison.Ordinal for ids.");
        Console.WriteLine("\"TITLE\".Equals(\"title\", Ordinal): " + "TITLE".Equals("title", StringComparison.Ordinal)
            + ", OrdinalIgnoreCase: " + "TITLE".Equals("title", StringComparison.OrdinalIgnoreCase));
    }

    // 2) Async: fire-and-forget loses the error.
    static async Task AsyncBug()
    {
        Task lost = Task.Run(() => { throw new InvalidOperationException("email failed"); });
        await Task.Delay(50);
        Console.WriteLine("fire-and-forget task faulted but nobody noticed: " + lost.IsFaulted);
    }

    // 3) Time: store UTC, convert only to show.
    static void TimeBug()
    {
        var stored = new DateTime(2026, 3, 29, 0, 30, 0, DateTimeKind.Utc);
        TimeZoneInfo tz = TimeZoneInfo.FindSystemTimeZoneById("UTC");
        Console.WriteLine("stored UTC " + stored.ToString("u") + " -> shown in zone: " + TimeZoneInfo.ConvertTimeFromUtc(stored, tz).ToString("u"));
        Console.WriteLine("Local time around the daylight-saving change is ambiguous; UTC never is.");
    }

    static async Task Main()
    {
        CultureBug();
        await AsyncBug();
        TimeBug();
        Console.WriteLine("Checklist order: correctness, async, security, data access, design, tests, style (tools do style).");
        // Time O(1), space O(1).
    }
}

using System;

public class PriceClient
{
    // Version 1.x API: used by many teams. We want to replace it with a version that supports a currency.

    // Step 1: add the new way (v2.0 would change the meaning of the old one).
    public decimal GetPrice(int productId, string currency)
    {
        return currency == "EUR" ? productId * 1.1m : productId * 1.0m;
    }

    // Step 2: keep the old method working, forward it to the new one, and warn callers.
    [Obsolete("Use GetPrice(productId, currency). This method will be removed in 3.0.")]
    public decimal GetPrice(int productId)
    {
        return GetPrice(productId, "USD");          // old behaviour = USD
    }
}

class Program
{
    static void Main()
    {
        var client = new PriceClient();
#pragma warning disable CS0618                     // existing callers show the warning at build time
        decimal oldWay = client.GetPrice(10);
#pragma warning restore CS0618
        decimal newWay = client.GetPrice(10, "EUR");
        Console.WriteLine("old call (still works): " + oldWay + " USD");
        Console.WriteLine("new call:               " + newWay + " EUR");

        Console.WriteLine("Timeline: 2.0 add new + [Obsolete] old (warning), 2.x remove warnings in all teams,");
        Console.WriteLine("          3.0 remove the old method (major version = breaking changes allowed).");
        Console.WriteLine("Source break: renamed method. Binary break: old DLL fails to run. Behaviour break: same signature, new meaning.");
        // Time O(1), space O(1).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

// Value object: no identity, immutable, equal when its values are equal.
readonly record struct Money(decimal Amount, string Currency)
{
    public static Money operator +(Money a, Money b)
    {
        if (a.Currency != b.Currency) throw new InvalidOperationException("different currencies");
        return new Money(a.Amount + b.Amount, a.Currency);
    }
}

// Entity inside the aggregate: has an identity (the product id).
class OrderLine
{
    public int ProductId { get; }
    public int Quantity { get; }
    public Money Price { get; }
    public OrderLine(int productId, int quantity, Money price) { ProductId = productId; Quantity = quantity; Price = price; }
}

// Aggregate root: the only way in. It protects the rules, so callers cannot skip them.
class Order
{
    private readonly List<OrderLine> _lines = new List<OrderLine>();
    public Guid Id { get; } = Guid.NewGuid();
    public bool IsPlaced { get; private set; }
    public IReadOnlyList<OrderLine> Lines => _lines;

    public void AddLine(int productId, int quantity, Money price)
    {
        if (IsPlaced) throw new InvalidOperationException("a placed order cannot change");
        if (quantity <= 0) throw new ArgumentException("quantity must be positive");
        _lines.Add(new OrderLine(productId, quantity, price));
    }

    public Money Total() { return _lines.Aggregate(new Money(0, "EUR"), (sum, l) => sum + new Money(l.Price.Amount * l.Quantity, l.Price.Currency)); }

    public void Place()
    {
        if (_lines.Count == 0) throw new InvalidOperationException("an order needs at least one line");
        IsPlaced = true;
    }
}

class Program
{
    static void Main()
    {
        Console.WriteLine("Money equality: " + (new Money(5, "EUR") == new Money(5, "EUR")) + " (value object)");
        var order = new Order();
        try { order.Place(); } catch (InvalidOperationException e) { Console.WriteLine("rule: " + e.Message); }
        order.AddLine(1, 2, new Money(10m, "EUR"));
        order.AddLine(2, 1, new Money(5m, "EUR"));
        order.Place();
        Console.WriteLine("placed: " + order.IsPlaced + ", lines " + order.Lines.Count + ", total " + order.Total().Amount + " EUR");
        try { order.AddLine(3, 1, new Money(1m, "EUR")); } catch (InvalidOperationException e) { Console.WriteLine("rule: " + e.Message); }
        // Time O(lines), space O(lines).
    }
}
